const TYPE_LABELS = { income: "收入", expense: "支出" };
const CATEGORIES = {
  income: ["工资", "奖金", "兼职", "投资收益", "红包", "其他收入"],
  expense: ["餐饮", "交通", "购物", "居住", "水电", "通讯", "医疗", "教育", "娱乐", "其他支出"]
};

const els = {
  monthFilter: document.getElementById("monthFilter"),
  statIncome: document.getElementById("statIncome"),
  statExpense: document.getElementById("statExpense"),
  statBalance: document.getElementById("statBalance"),
  statCount: document.getElementById("statCount"),
  form: document.getElementById("entryForm"),
  fieldDate: document.getElementById("fieldDate"),
  fieldType: document.getElementById("fieldType"),
  fieldCategory: document.getElementById("fieldCategory"),
  fieldAmount: document.getElementById("fieldAmount"),
  fieldNote: document.getElementById("fieldNote"),
  formMessage: document.getElementById("formMessage"),
  recordList: document.getElementById("recordList"),
  emptyTip: document.getElementById("emptyTip"),
  listHint: document.getElementById("listHint"),
  dialogMask: document.getElementById("dialogMask"),
  dialogText: document.getElementById("dialogText"),
  dialogCancel: document.getElementById("dialogCancel"),
  dialogConfirm: document.getElementById("dialogConfirm")
};

let state = null;
let activeMonth = "";
let pendingDeleteId = null;

function pad2(n) {
  return String(n).padStart(2, "0");
}

function todayISO() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function currentMonth() {
  return todayISO().slice(0, 7);
}

function monthOf(dateStr) {
  return typeof dateStr === "string" ? dateStr.slice(0, 7) : "";
}

function formatMoney(value) {
  const n = Number(value) || 0;
  const sign = n < 0 ? "-" : "";
  return sign + "¥" + Math.abs(n).toFixed(2);
}

function normalizeRecord(raw) {
  const rec = raw && typeof raw === "object" ? raw : {};
  const type = rec.type === "income" ? "income" : "expense";
  const amount = Number(rec.amount);
  return {
    id: typeof rec.id === "string" && rec.id ? rec.id : "rec_" + Math.random().toString(36).slice(2, 10),
    date: typeof rec.date === "string" && rec.date ? rec.date : todayISO(),
    type: type,
    category: typeof rec.category === "string" && rec.category ? rec.category : CATEGORIES[type][0],
    amount: Number.isFinite(amount) ? amount : 0,
    note: typeof rec.note === "string" ? rec.note : ""
  };
}

function normalizeState(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const next = Object.assign({}, src);
  const list = Array.isArray(src.records) ? src.records : [];
  next.records = list.map(normalizeRecord);
  return next;
}

function makeId() {
  return "rec_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
}

function fillCategoryOptions(type, keepValue) {
  const options = CATEGORIES[type] || [];
  els.fieldCategory.textContent = "";
  options.forEach(function (name) {
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = name;
    els.fieldCategory.appendChild(opt);
  });
  if (keepValue && options.indexOf(keepValue) !== -1) {
    els.fieldCategory.value = keepValue;
  }
}

function setMessage(text, ok) {
  els.formMessage.textContent = text || "";
  els.formMessage.classList.toggle("is-ok", !!ok);
}

function recordsOfMonth(month) {
  return state.records.filter(function (r) {
    return monthOf(r.date) === month;
  });
}

function sortRecords(list) {
  return list.slice().sort(function (a, b) {
    if (a.date === b.date) {
      return a.id < b.id ? 1 : -1;
    }
    return a.date < b.date ? 1 : -1;
  });
}

function renderStats(list) {
  let income = 0;
  let expense = 0;
  list.forEach(function (r) {
    if (r.type === "income") {
      income += r.amount;
    } else {
      expense += r.amount;
    }
  });
  els.statIncome.textContent = formatMoney(income);
  els.statExpense.textContent = formatMoney(expense);
  els.statBalance.textContent = formatMoney(income - expense);
  els.statCount.textContent = String(list.length);
}

function buildRecordItem(record) {
  const li = document.createElement("li");
  li.className = "record-item " + (record.type === "income" ? "is-income" : "is-expense");
  li.dataset.recordId = record.id;

  const main = document.createElement("div");
  main.className = "record-main";

  const top = document.createElement("div");
  top.className = "record-top";

  const cat = document.createElement("span");
  cat.className = "record-category";
  cat.textContent = record.category;
  top.appendChild(cat);

  const tag = document.createElement("span");
  tag.className = "tag " + (record.type === "income" ? "tag-income" : "tag-expense");
  tag.textContent = TYPE_LABELS[record.type];
  top.appendChild(tag);

  main.appendChild(top);

  const meta = document.createElement("div");
  meta.className = "record-meta";
  const dateSpan = document.createElement("span");
  dateSpan.textContent = record.date;
  meta.appendChild(dateSpan);
  main.appendChild(meta);

  if (record.note) {
    const note = document.createElement("div");
    note.className = "record-note";
    note.textContent = record.note;
    main.appendChild(note);
  }

  li.appendChild(main);

  const amount = document.createElement("span");
  amount.className = "record-amount " + (record.type === "income" ? "is-income" : "is-expense");
  amount.textContent = (record.type === "income" ? "+" : "-") + formatMoney(record.amount);
  li.appendChild(amount);

  const delBtn = document.createElement("button");
  delBtn.type = "button";
  delBtn.className = "btn btn-ghost btn-small";
  delBtn.dataset.action = "delete";
  delBtn.dataset.recordId = record.id;
  delBtn.textContent = "删除";
  li.appendChild(delBtn);

  return li;
}

function renderList() {
  const list = sortRecords(recordsOfMonth(activeMonth));
  els.recordList.textContent = "";
  list.forEach(function (record) {
    els.recordList.appendChild(buildRecordItem(record));
  });
  els.emptyTip.hidden = list.length > 0;
  els.listHint.textContent = activeMonth + " 共 " + list.length + " 笔记录";
  renderStats(list);
}

function renderAll() {
  renderList();
}

function openDialog(record) {
  pendingDeleteId = record.id;
  els.dialogText.textContent =
    "确定删除这条记录吗？" +
    record.date + " · " + TYPE_LABELS[record.type] + " · " + record.category +
    " · " + formatMoney(record.amount) + (record.note ? " · " + record.note : "") +
    "。删除后无法恢复。";
  els.dialogMask.hidden = false;
  els.dialogConfirm.focus();
}

function closeDialog() {
  pendingDeleteId = null;
  els.dialogMask.hidden = true;
}

async function persist(nextState, errorMessage) {
  try {
    await appStore.setState(nextState);
    state = nextState;
    return true;
  } catch (err) {
    setMessage(errorMessage || "保存失败，请重试。", false);
    return false;
  }
}

async function handleSubmit(event) {
  event.preventDefault();
  const date = els.fieldDate.value;
  const type = els.fieldType.value === "income" ? "income" : "expense";
  const category = els.fieldCategory.value;
  const amountRaw = els.fieldAmount.value.trim();
  const note = els.fieldNote.value.trim();

  if (!date) {
    setMessage("请选择日期。", false);
    return;
  }
  if (!category) {
    setMessage("请选择分类。", false);
    return;
  }
  const amount = Number(amountRaw);
  if (!amountRaw || !Number.isFinite(amount) || amount <= 0) {
    setMessage("请输入大于 0 的金额。", false);
    return;
  }

  const record = normalizeRecord({
    id: makeId(),
    date: date,
    type: type,
    category: category,
    amount: Math.round(amount * 100) / 100,
    note: note
  });

  const next = Object.assign({}, state, { records: state.records.concat([record]) });
  const ok = await persist(next, "保存失败，记录未添加，请重试。");
  if (!ok) {
    return;
  }

  activeMonth = monthOf(record.date);
  els.monthFilter.value = activeMonth;
  els.fieldAmount.value = "";
  els.fieldNote.value = "";
  setMessage("已添加：" + TYPE_LABELS[record.type] + " " + formatMoney(record.amount), true);
  renderAll();
}

async function handleDelete(id) {
  const target = state.records.filter(function (r) {
    return r.id === id;
  })[0];
  if (!target) {
    closeDialog();
    return;
  }
  const next = Object.assign({}, state, {
    records: state.records.filter(function (r) {
      return r.id !== id;
    })
  });
  const ok = await persist(next, "删除失败，请重试。");
  closeDialog();
  if (!ok) {
    return;
  }
  setMessage("已删除该条记录。", true);
  renderAll();
}

function handleListClick(event) {
  const btn = event.target.closest("button[data-action='delete']");
  if (!btn) {
    return;
  }
  const id = btn.dataset.recordId;
  const record = state.records.filter(function (r) {
    return r.id === id;
  })[0];
  if (!record) {
    return;
  }
  openDialog(record);
}

async function init() {
  const raw = await appStore.getState();
  state = normalizeState(raw);

  if (!Array.isArray(raw && raw.records)) {
    const seeded = Object.assign({}, state, { records: [] });
    try {
      await appStore.setState(seeded);
      state = seeded;
    } catch (err) {
      setMessage("初始化数据失败，请刷新重试。", false);
    }
  }

  activeMonth = currentMonth();
  els.monthFilter.value = activeMonth;
  els.fieldDate.value = todayISO();
  els.fieldType.value = "expense";
  fillCategoryOptions("expense", null);

  els.monthFilter.addEventListener("change", function () {
    activeMonth = els.monthFilter.value || currentMonth();
    renderAll();
  });

  els.fieldType.addEventListener("change", function () {
    fillCategoryOptions(els.fieldType.value, null);
  });

  els.form.addEventListener("submit", handleSubmit);

  els.form.addEventListener("reset", function () {
    setTimeout(function () {
      els.fieldDate.value = todayISO();
      els.fieldType.value = "expense";
      fillCategoryOptions("expense", null);
      setMessage("", false);
    }, 0);
  });

  els.recordList.addEventListener("click", handleListClick);
  els.dialogCancel.addEventListener("click", closeDialog);
  els.dialogConfirm.addEventListener("click", function () {
    if (pendingDeleteId) {
      handleDelete(pendingDeleteId);
    } else {
      closeDialog();
    }
  });
  els.dialogMask.addEventListener("click", function (event) {
    if (event.target === els.dialogMask) {
      closeDialog();
    }
  });
  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.dialogMask.hidden) {
      closeDialog();
    }
  });

  renderAll();
}

await init();

