:root {
  --bg-deep: #0f1b2a;
  --bg-mid: #16283d;
  --surface: #1d3348;
  --surface-soft: #24405a;
  --border: #33526f;
  --text: #eaf2fb;
  --text-dim: #a8bed4;
  --accent: #4fc3a1;
  --accent-strong: #37a888;
  --income: #4fc3a1;
  --expense: #ff8a7a;
  --danger: #e05a4f;
  --shadow: 0 18px 40px rgba(4, 12, 22, 0.45);
}

#app {
  min-height: 100vh;
  background: radial-gradient(circle at 12% 8%, #1e3a55 0%, var(--bg-mid) 42%, var(--bg-deep) 100%);
  background-attachment: fixed;
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, sans-serif;
  padding: 28px 20px 56px;
  box-sizing: border-box;
}

#app * {
  box-sizing: border-box;
}

.ledger-app {
  max-width: 1040px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.app-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.app-header h1 {
  margin: 0 0 6px;
  font-size: 26px;
  letter-spacing: 1px;
  color: var(--text);
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: var(--text-dim);
}

.month-picker {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.month-picker label {
  font-size: 12px;
  color: var(--text-dim);
  letter-spacing: 0.5px;
}

.month-input {
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 9px 12px;
  font-size: 14px;
  font-family: inherit;
  color-scheme: dark;
}

.month-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(79, 195, 161, 0.22);
}

.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 14px;
}

.stat-card {
  background: linear-gradient(160deg, var(--surface) 0%, var(--surface-soft) 100%);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: var(--shadow);
}

.stat-label {
  font-size: 12px;
  color: var(--text-dim);
  letter-spacing: 0.6px;
}

.stat-value {
  font-size: 22px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.stat-income .stat-value {
  color: var(--income);
}

.stat-expense .stat-value {
  color: var(--expense);
}

.stat-balance .stat-value {
  color: var(--text);
}

.stat-count .stat-value {
  color: var(--text-dim);
}

.panel {
  background: rgba(29, 51, 72, 0.86);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 20px 22px 22px;
  box-shadow: var(--shadow);
}

.panel-title {
  margin: 0 0 16px;
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.5px;
}

.entry-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px 16px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-wide {
  grid-column: 1 / -1;
}

.field label {
  font-size: 12px;
  color: var(--text-dim);
  letter-spacing: 0.5px;
}

.control {
  width: 100%;
  background: #14273a;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 14px;
  font-family: inherit;
  color-scheme: dark;
}

.control::placeholder {
  color: #6f8aa4;
}

.control:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(79, 195, 161, 0.22);
}

select.control {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-dim) 50%),
    linear-gradient(135deg, var(--text-dim) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 20px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.18s ease, border-color 0.18s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent);
  color: #08231c;
  font-weight: 600;
}

.btn-primary:hover {
  background: var(--accent-strong);
}

.btn-ghost {
  background: transparent;
  color: var(--text-dim);
  border-color: var(--border);
}

.btn-ghost:hover {
  color: var(--text);
  border-color: var(--accent);
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  font-weight: 600;
}

.btn-danger:hover {
  background: #c9483e;
}

.btn-small {
  padding: 6px 14px;
  font-size: 13px;
}

.form-message {
  grid-column: 1 / -1;
  margin: 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--expense);
}

.form-message.is-ok {
  color: var(--income);
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.list-hint {
  font-size: 12px;
  color: var(--text-dim);
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  background: #16293c;
  border: 1px solid var(--border);
  border-left: 4px solid var(--border);
  border-radius: 12px;
}

.record-item.is-income {
  border-left-color: var(--income);
}

.record-item.is-expense {
  border-left-color: var(--expense);
}

.record-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.record-top {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.record-category {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
}

.tag {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid currentColor;
}

.tag-income {
  color: var(--income);
}

.tag-expense {
  color: var(--expense);
}

.record-meta {
  font-size: 12px;
  color: var(--text-dim);
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.record-note {
  font-size: 13px;
  color: #c7d8e8;
  word-break: break-word;
}

.record-amount {
  font-size: 17px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.record-amount.is-income {
  color: var(--income);
}

.record-amount.is-expense {
  color: var(--expense);
}

.empty-tip {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--text-dim);
  text-align: center;
  padding: 22px 10px;
  border: 1px dashed var(--border);
  border-radius: 12px;
}

.empty-tip[hidden] {
  display: none;
}

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(6, 14, 24, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-mask[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 22px;
  box-shadow: 0 24px 60px rgba(3, 9, 18, 0.6);
}

.dialog-title {
  margin: 0 0 10px;
  font-size: 17px;
  color: var(--text);
}

.dialog-text {
  margin: 0 0 20px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--text-dim);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 560px) {
  #app {
    padding: 18px 12px 40px;
  }

  .record-item {
    flex-wrap: wrap;
  }

  .record-amount {
    margin-left: auto;
  }
}
